 "content": "def transform(grid):
    """Draw color-2 connectors through aligned marker groups and close the bounding frame."""
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = next(v for v in counts if v != background)
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == marker]
    out = [row[:] for row in grid]
    rmin, rmax = min(r for r, c in points), max(r for r, c in points)
    cmin, cmax = min(c for r, c in points), max(c for r, c in points)
    # Connect marker pairs in a row/column, with the connector color distinct from markers.
    for r in range(rmin, rmax + 1):
        cs = [c for rr, c in points if rr == r]
        if len(cs) >= 2:
            for c in range(min(cs), max(cs) + 1):
                if out[r][c] == background:
                    out[r][c] = 2
    for c in range(cmin, cmax + 1):
        rs = [r for r, cc in points if cc == c]
        if len(rs) >= 2:
            for r in range(min(rs), max(rs) + 1):
                if out[r][c] == background:
                    out[r][c] = 2
    # Enclose the full scatter by a rectangular outline.
    for c in range(cmin, cmax + 1):
        if out[rmin][c] == background: out[rmin][c] = 2
        if out[rmax][c] == background: out[rmax][c] = 2
    for r in range(rmin, rmax + 1):
        if out[r][cmin] == background: out[r][cmin] = 2
        if out[r][cmax] == background: out[r][cmax] = 2
    return out
