    """Draw color-2 connectors between separated marker islands."""
    from collections import Counter, deque

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marker = next(v for v in counts if v != bg)
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Identify 4-connected components of the marker pixels.
    unseen = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker}
    comps = []
    while unseen:
        start = unseen.pop()
        comp = {start}
        q = deque([start])
        while q:
            r, c = q.popleft()
            for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if (nr,nc) in unseen:
                    unseen.remove((nr,nc)); comp.add((nr,nc)); q.append((nr,nc))
        comps.append(comp)

    # Only connect collinear marker components when an intervening marker pixel
    # in the same row/column establishes the bridge direction. Gaps are color 2.
    for r in range(h):
        cols = sorted(c for rr,c in ((p for comp in comps for p in comp)) if rr == r)
        for a,b in zip(cols, cols[1:]):
            if b > a+1:
                for c in range(a+1,b):
                    if out[r][c] == bg: out[r][c] = 2
    for c in range(w):
        rows = sorted(r for r,cc in ((p for comp in comps for p in comp)) if cc == c)
        for a,b in zip(rows, rows[1:]):
            if b > a+1:
                for r in range(a+1,b):
                    if out[r][c] == bg: out[r][c] = 2

    # At boundary marker bars, fill missing cells within each bar's extent;
    # the observed separated components determine bars rather than the whole box.
    allpts = [p for comp in comps for p in comp]
    rmin,rmax=min(r for r,c in allpts),max(r for r,c in allpts)
    cmin,cmax=min(c for r,c in allpts),max(c for r,c in allpts)
    for r in (rmin,rmax):
